The code window is 3000 ms and the code is 3 presses. Presses come at t = 0, 1500, 3200, 3500 and 4000 ms, and tamam() is called for each of them. What is the output?

```
const unsigned long PENCERE = 3000;
int basis = 0;
unsigned long ilk = 0;

bool tamam(unsigned long t) {
  if (basis == 0 || t - ilk > PENCERE) {
    basis = 1;
    ilk = t;
  } else {
    basis++;
  }
  return basis >= 3;
}

void setup() {
  Serial.begin(9600);
  unsigned long zamanlar[] = {0, 1500, 3200, 3500, 4000};
  for (int i = 0; i < 5; i++) {
    Serial.print(tamam(zamanlar[i]) ? "E " : "H ");
  }
  Serial.println();
}

void loop() {}
```

